CREATE TABLE IF NOT EXISTS lesson_settings (id INTEGER PRIMARY KEY CHECK (id = 1), era_title TEXT NOT NULL, song_title TEXT NOT NULL, audio_or_link_url TEXT NOT NULL DEFAULT '', historical_context TEXT NOT NULL, artwork_note TEXT NOT NULL, empathy_prompt TEXT NOT NULL, share_with_class INTEGER NOT NULL DEFAULT 1, is_customized INTEGER NOT NULL DEFAULT 0, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS lesson_artworks (slot_index INTEGER PRIMARY KEY CHECK (slot_index >= 0 AND slot_index <= 3), title TEXT NOT NULL DEFAULT '', image_url TEXT NOT NULL DEFAULT '', description TEXT NOT NULL DEFAULT '', updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS student_responses (id TEXT PRIMARY KEY, student_id TEXT NOT NULL, student_name TEXT NOT NULL, class_group TEXT NOT NULL DEFAULT '', reflection_text TEXT NOT NULL, present_connection TEXT NOT NULL DEFAULT '', is_public INTEGER NOT NULL DEFAULT 0, rubric_level TEXT NOT NULL DEFAULT '', teacher_feedback TEXT NOT NULL DEFAULT '', edit_token TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_student_responses_public_updated ON student_responses (is_public, updated_at DESC);
CREATE INDEX IF NOT EXISTS idx_student_responses_student_id ON student_responses (student_id);
